import numpy as np
from scipy.optimize import least_squares
def model(p):
    w,k,kx=p[0],p[1],p[2]
    c=np.cos(w*t); s=np.sin(w*t)
    A=np.column_stack([np.ones_like(t),x,v,np.sin(k*v),c,s,c*x,c*v,s*v,s*x,x**3,v*np.abs(v),np.sin(kx*x)])
    return A
def fitp(p):
    A=model(p)
    cc,*_=np.linalg.lstsq(A,dv_dt,rcond=None)
    return dv_dt-A@cc
best=None
for w0 in [0.38,0.4,0.41,0.43]:
    for k0 in [0.5,1.0,1.5]:
        for kx0 in [0.5,1.0,2.0]:
            try:
                r=least_squares(fitp,[w0,k0,kx0],bounds=([0.1,0.05,0.05],[1.5,5,5]))
                e=(r.fun**2).mean()/dv_dt.var()
                if best is None or e<best[0]: best=(e,r.x)
            except Exception as ex:
                pass
print(best)
